const job = $input.first().json.job;
if (!job) return [];
const op = job.operation;
const resource = /^([a-z][a-z0-9_]{0,30}):([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})$/.exec(op?.resource || '');
if (op?.kind !== 'supabase_row' || !resource || !/^"[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"$/.test(op.afterVersion) || !op.before || !op.after || !Object.keys(op.before).length || Object.keys(op.before).sort().join(',') !== Object.keys(op.after).sort().join(',')) throw new Error('Unsupported Supabase job. No write attempted.');
return [{json:{job,alias:resource[1],rowId:resource[2]}}];

const op = $('Validate job').first().json.job.operation;
const response = $input.first().json;
let result = null;
if (response.statusCode !== 200) result = {status:'failed',detail:'Supabase row could not be read. No write attempted.'};
else if ('"'+response.body?.version+'"' !== op.afterVersion || !Object.entries(op.after).every(([k,v]) => response.body?.record && Object.hasOwn(response.body.record,k) && JSON.stringify(response.body.record[k]) === JSON.stringify(v))) result = {status:'conflict',detail:'The row changed after the automation. Current data was preserved.'};
else if (Object.values(op.before).includes(null)) result = {status:'manual',detail:'Null fields are outside this adapter contract. No write attempted.'};
return [{json:{canRestore:!result,result}}];

const response = $input.first().json;
const op = $('Validate job').first().json.job.operation;
const code = response.statusCode, body = response.body;
const equal = (a,b) => a && b && Object.keys(a).length === Object.keys(b).length && Object.entries(a).every(([k,v])=>Object.hasOwn(b,k) && JSON.stringify(b[k]) === JSON.stringify(v));
let result;
if (code === 409 || code === 412) result = {status:'conflict',detail:'The database rejected recovery because the row or recorded fields changed.'};
else if (!code || code >= 500) result = {status:'uncertain',detail:'The write outcome is unknown. Inspect the row; do not automatically retry.'};
else if (code < 200 || code >= 300) result = {status:'failed',detail:'Supabase rejected restoration with HTTP '+code+'.'};
else if (!body || !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(body.version) || '"'+body.version+'"' === op.afterVersion || !equal(body.before,op.after) || !equal(body.after,op.before)) result = {status:'uncertain',detail:'The database response did not confirm the original fields and a new revision.'};
else result = {status:'restored',restoredVersion:'"'+body.version+'"',detail:'Original fields restored in a version-checked PostgreSQL transaction.'};
return [{json:{result}}];

const config = $input.first().json;
function checkedBase(value) {
  if (typeof value !== 'string' || /[\s\\]/.test(value)) throw new Error('Configure a plain trusted base URL.');
  const match = /^(https?):\/\/([^\/?#]+)(\/[^?#]*)?$/.exec(value);
  if (!match || !/^(\[[0-9a-fA-F:]+\]|[a-zA-Z0-9.-]+)(:\d{1,5})?$/.test(match[2])) throw new Error('URL credentials, queries, fragments and invalid hosts are not permitted.');
  if (match[1] !== 'https' && !/^(localhost|127\.0\.0\.1|host\.docker\.internal)(:\d{1,5})?$/i.test(match[2])) throw new Error('Remote endpoints require HTTPS before sending credentials.');
  return value.replace(/\/$/, '');
}

const supabaseBaseUrl = checkedBase(config.supabaseBaseUrl);
if (!/^https?:\/\/[^/]+$/.test(supabaseBaseUrl)) throw new Error('Supabase must be a project origin without a path.');
const connection=config.connection||'default';
if(typeof connection!=='string'||!/^[a-z][a-z0-9_-]{0,62}$/.test(connection)) throw new Error('Configure a connection name matching the recorded operation.');
return [{json:{connection,rewindBaseUrl:checkedBase(config.rewindBaseUrl),supabaseBaseUrl}}];
